                load2 = route_load(r2)
                a = 0
                while a < len(r1):
                    b = 0
                    while b < len(r2):
                        n1 = r1[a]
                        n2 = r2[b]
                        nl1 = load1 - demands[n1] + demands[n2]
                        nl2 = load2 - demands[n2] + demands[n1]
                        if nl1 <= capacity and nl2 <= capacity:
                            # swap delta
                            p1 = depot if a == 0 else r1[a - 1]
                            q1 = depot if a + 1 == len(r1) else r1[a + 1]
                            p2 = depot if b == 0 else r2[b - 1]
                            q2 = depot if b + 1 == len(r2) else r2[b + 1]
                            if i == j:
                                b += 1
                                continue
                            delta = (
                                dist(p1, n2) + dist(n2, q1) - dist(p1, n1) - dist(n1, q1)
                                + dist(p2, n1) + dist(n1, q2) - dist(p2, n2) - dist(n2, q2)
                            )
                            if delta < -1e-12:
                                best_move = ("swap", i, a, j, b, delta)
                                break
                        b += 1
                    if best_move is not None:
                        break
                    a += 1
                if best_move is not None:
                    break
                j += 1
            if best_move is not None:
                break
            i += 1

        if best_move is not None:
            _, i, a, j, b, _ = best_move
            r1 = routes[i]
            r2 = routes[j]
            r1[a], r2[b] = r2[b], r1[a]
            changed = True

    # Final cleanup: remove empties and ensure all customers once.
    cleaned = []
    seen = {}
    for r in routes:
        nr = []
        for n in r:
            if n not in seen:
                seen[n] = 1
                nr.append(n)
        if nr:
            cleaned.append(nr)

    missing = []
    for n in customers:
        if n not in seen:
            missing.append(n)

    for n in missing:
        best_r = -1
        best_pos = 0
        best_delta = None
        for i in range(len(cleaned)):
            if route_load(cleaned[i]) + demands[n] > capacity:
                continue
            r = cleaned[i]
            for pos in range(len(r) + 1):
                prev = depot if pos == 0 else r[pos - 1]
                nxt = depot if pos == len(r) else r[pos]
                delta = dist(prev, n) + dist(n, nxt) - dist(prev, nxt)
                if best_delta is None or delta < best_delta:
                    best_delta = delta
                    best_r = i
                    best_pos = pos
        if best_r == -1:
            cleaned.append([n])
        else:
            cleaned[best_r].insert(best_pos, n)

    return cleaned
